"""Sparse-node IPv6 pipeline compiler and lookup engine.

Reads one JSON request per line on stdin, writes one JSON response per line on
stdout.  Supports the "compile" and "lookup" operations described in the task
statement.  All arithmetic on bit budgets and utilisation ratios is exact
integer arithmetic.
"""
import json
import math
import sys

MASK128 = (1 << 128) - 1
MASK64 = 0xFFFFFFFFFFFFFFFF

INVALID_RESP = b'{"status":"invalid"}\n'
INFEASIBLE_RESP = b'{"status":"infeasible"}\n'

MAX_VALUES = 2000000
MAX_DEPTH = 64

# ---------------------------------------------------------------- exceptions


class Invalid(Exception):
    pass


# ---------------------------------------------------------------- type checks


def is_int(x):
    return x.__class__ is int


def is_str(x):
    return x.__class__ is str


def is_list(x):
    return x.__class__ is list


def is_dict(x):
    return x.__class__ is dict


# ---------------------------------------------------------------- ipv6 text

_HEX = frozenset('0123456789abcdefABCDEF')
_ALLOWED = frozenset('0123456789abcdefABCDEF:')
_DEC = frozenset('0123456789')

_parse_cache = {}


def parse_ipv6(s):
    """Strict colon separated hexadecimal notation.  Returns int or None."""
    if not is_str(s):
        return None
    r = _parse_cache.get(s)
    if r is not None:
        return r[0] if r[0] is not None else None
    v = _parse_ipv6(s)
    if len(_parse_cache) < 150000:
        _parse_cache[s] = (v,)
    return v


def _parse_ipv6(s):
    n = len(s)
    if n == 0 or n > 39:
        return None
    for ch in s:
        if ch not in _ALLOWED:
            return None
    i = s.find('::')
    if i >= 0:
        if s.find('::', i + 1) >= 0:
            return None
        head = s[:i]
        tail = s[i + 2:]
        left = head.split(':') if head else []
        right = tail.split(':') if tail else []
        cnt = len(left) + len(right)
        if cnt > 7:
            return None
        for g in left:
            if not (1 <= len(g) <= 4):
                return None
            for ch in g:
                if ch not in _HEX:
                    return None
        for g in right:
            if not (1 <= len(g) <= 4):
                return None
            for ch in g:
                if ch not in _HEX:
                    return None
        groups = left + ['0'] * (8 - cnt) + right
    else:
        groups = s.split(':')
        if len(groups) != 8:
            return None
        for g in groups:
            if not (1 <= len(g) <= 4):
                return None
            for ch in g:
                if ch not in _HEX:
                    return None
    v = 0
    for g in groups:
        v = (v << 16) | int(g, 16)
    return v


_canon_cache = {}


def canon_addr(a):
    """Canonical pure hexadecimal text form of a 128 bit address."""

    """Canonical pure hexadecimal text form of a 128 bit address."""
    r = _canon_cache.get(a)
    if r is not None:
        return r
    g0 = (a >> 112) & 0xFFFF
    g1 = (a >> 96) & 0xFFFF
    g2 = (a >> 80) & 0xFFFF
    g3 = (a >> 64) & 0xFFFF
    g4 = (a >> 48) & 0xFFFF
    g5 = (a >> 32) & 0xFFFF
    g6 = (a >> 16) & 0xFFFF
    g7 = a & 0xFFFF
    groups = (g0, g1, g2, g3, g4, g5, g6, g7)
    best_i = -1
    best_l = 0
    i = 0
    while i < 8:
        if groups[i] == 0:
            j = i + 1
            while j < 8 and groups[j] == 0:
                j += 1
            if j - i > best_l:
                best_l = j - i
                best_i = i
            i = j
        else:
            i += 1
    if best_l >= 2:
        left = ':'.join(format(x, 'x') for x in groups[:best_i])
        right = ':'.join(format(x, 'x') for x in groups[best_i + best_l:])
        s = left + '::' + right
    else:
        s = ':'.join(format(x, 'x') for x in groups)
    if len(_canon_cache) < 150000:
        _canon_cache[a] = s
    return s


def canon_prefix(a, length):
    return canon_addr(a) + '/' + str(length)


def parse_prefix(s):
    """Parse '<ipv6>/<len>'; returns (addr, length) or None."""
    if not is_str(s):
        return None
    i = s.find('/')
    if i < 0 or s.find('/', i + 1) >= 0:
        return None
    ls = s[i + 1:]
    ln = len(ls)
    if ln == 0 or ln > 3:
        return None
    if ls == '0':
        length = 0
    else:
        if ls[0] not in '123456789':
            return None
        for ch in ls[1:]:
            if ch not in _DEC:
                return None
        length = int(ls)
        if length > 128:
            return None
    a = parse_ipv6(s[:i])
    if a is None:
        return None
    if a & HMASK[length]:
