            tot += align64(cost)
        stages.append(nodes)
        used.append(tot)
    return stages, used


def peak_of(used, caps):
    bn, bd = 0, 1
    for u, c in zip(used, caps):
        if u * bd > bn * c:
            bn, bd = u, c
    g = math.gcd(bn, bd)
    if g == 0:
        g = 1
    return bn // g, bd // g


def image_to_json(caps, ms, cuts, stages, used, peak):
    out_stages = []
    S = len(cuts) - 1
    for i in range(S):
        b = cuts[i]
        e = cuts[i + 1]
        nodes = []
        for (na, rules, edges) in stages[i]:
            nodes.append({
                'prefix': canon_prefix(na, b),
                'rules': [{'prefix': canon_prefix(a, l), 'hop': h}
