        'status': 'ok',
        'capacities': list(caps),
        'max_stride': ms,
        'cuts': list(cuts),
        'stages': out_stages,
        'used_bits': list(used),
        'peak': {'num': peak[0], 'den': peak[1]},
    }


# ---------------------------------------------------------------- optimiser


def rat_less(a, b):
    return a[0] * b[1] < b[0] * a[1]


def py_utab(fs, ms):
