                    raise Invalid('child')
                ep = ed['prefix']
                pr3 = parse_prefix(ep)
                if pr3 is None:
                    raise Invalid('edge prefix')
                if pr3[1] != e or canon_prefix(pr3[0], e) != ep:
                    raise Invalid('edge prefix form')
                a = pr3[0]
                if prev_e is not None and a <= prev_e:
                    raise Invalid('edge order')
                prev_e = a
                edges.append((a, ch))
            stage_nodes.append((na, tuple(rules), tuple(edges)))
        parsed.append(stage_nodes)

    if len(fib) > 2048:
        raise Invalid('fib size')
    seen = set()
    for (a, l, h) in fib:
        k = (a, l)
        if k in seen:
            raise Invalid('dup route')
        seen.add(k)
    for i in range(S - 1):
        e = cuts[i + 1]
        if e == 128:
            continue
        nn = len(parsed[i + 1])
        for (na, rules, edges) in parsed[i]:
            for (ea, ch) in edges:
                if ch < 0 or ch >= nn:
                    raise Invalid('child range')
                if parsed[i + 1][ch][0] != ea:
                    raise Invalid('child target')
    expected, used = build_layout(fib, cuts)
    for i in range(S):
        exp = expected[i]
        got = parsed[i]
        if len(exp) != len(got):
            raise Invalid('node count')
        for j in range(len(exp)):
            if exp[j] != got[j]:
                raise Invalid('node content')
    if len(ub) != len(used):
        raise Invalid('used len')
    for i in range(S):
        if ub[i] != used[i]:
            raise Invalid('used value mismatch')
        if used[i] > caps[i]:
            raise Invalid('capacity')
    num, den = peak_of(used, caps)
    if pn != num or pd != den:
        raise Invalid('peak mismatch')
    if num > den:
        raise Invalid('peak over')
    return fib, cuts, caps, ms, S


# ---------------------------------------------------------------- lookup


def py_lpm(rules, queries):
    by_len = {}
    for (a, l, h) in rules:
        d = by_len.get(l)
        if d is None:
            d = {}
            by_len[l] = d
        d[a] = h
    lengths = sorted(by_len.keys(), reverse=True)
    masks = [(l, TMASK[l]) for l in lengths]
    dicts = [by_len[l] for l in lengths]
    out = []
    for q in queries:
        res = None
        for k in range(len(lengths)):
            h = dicts[k].get(q & masks[k][1])
            if h is not None:
                res = (h, lengths[k])
                break
        out.append(res)
    return out


def do_lookup(obj):
    if set(obj.keys()) != {'op', 'image', 'addresses'}:
        raise Invalid('keys')
    addrs_raw = obj['addresses']
    if not is_list(addrs_raw) or len(addrs_raw) > 20000:
        raise Invalid('addresses')
    fib, cuts, caps, ms, S = validate_image(obj['image'])
    queries = []
    for s in addrs_raw:
        a = parse_ipv6(s)
        if a is None:
            raise Invalid('address')

            raise Invalid('address')
        queries.append(a)
    rules = [(a, l, h) for (a, l, h) in fib]
    res = None
    if _ACCEL is not None and _ACCEL.available and (rules or queries):
        try:
            res = _ACCEL.lpm_batch(rules, queries)
        except Exception:
            res = None
    if res is None:
        res = py_lpm(rules, queries)
    answers = []
    for (h, l) in res:
        if h < 0:
            answers.append({'hop': None, 'prefix_length': None})
        else:
            answers.append({'hop': h, 'prefix_length': l})
    return {'status': 'ok', 'answers': answers}


# ---------------------------------------------------------------- driver


def handle_line(line):
    try:
        if not line:
            return INVALID_RESP
        obj = parse_request(line)
        if not is_dict(obj):
            return INVALID_RESP
        op = obj.get('op')
        if op == 'compile':
            r = do_compile(obj)
        elif op == 'lookup':
            r = do_lookup(obj)
        else:
            return INVALID_RESP
        if r == 'infeasible':
            return INFEASIBLE_RESP
        return (json.dumps(r, separators=(',', ':'), ensure_ascii=True)
                .encode('ascii') + b'\n')
    except Invalid:
        return INVALID_RESP
    except Exception:
        return INVALID_RESP


def main(src_dir=None):
    global _ACCEL, _CROSS_CHECK
    import os
    if os.environ.get('SCAMP_NO_ACCEL') == '1':
        _ACCEL = None
    else:
        try:
            import scamp_accel
            if src_dir is None:
                src_dir = os.path.dirname(os.path.abspath(__file__))
            _ACCEL = scamp_accel.Accel(src_dir)
        except Exception:
            _ACCEL = None
    if os.environ.get('SCAMP_CROSS_CHECK') == '1':
        _CROSS_CHECK = True
    out = sys.stdout.buffer
    inp = sys.stdin.buffer
    while True:
        try:
            line = inp.readline()
        except Exception:
            break
        if not line:
            break
        if line.endswith(b'\n'):
            line = line[:-1]
        if line.endswith(b'\r'):
            line = line[:-1]
        try:
            resp = handle_line(line)
        except BaseException:
            resp = INVALID_RESP
        try:
            out.write(resp)
            out.flush()
        except Exception:
            break
    try:
        out.flush()
    except Exception:
        pass

